const root = $input.first().json;

function collectNamedArrays(value, found = []) {
  if (!value || typeof value !== "object") return found;
  if (Array.isArray(value.questions)) found.push(value.questions);
  if (Array.isArray(value.urlParameters)) found.push(value.urlParameters);
  if (Array.isArray(value.calculations)) found.push(value.calculations);
  if (Array.isArray(value)) {
    for (const item of value) collectNamedArrays(item, found);
  } else {
    for (const item of Object.values(value)) collectNamedArrays(item, found);
  }
  return found;
}

const fields = {};
for (const list of collectNamedArrays(root)) {
  for (const item of list) {
    if (!item || !item.name) continue;
    fields[String(item.name).trim()] = item.value ?? "";
  }
}

function pick(...keys) {
  for (const key of keys) {
    const value = fields[key];
    if (value !== undefined && value !== null && String(value).trim() !== "") {
      return String(value).trim();
    }
  }
  return "";
}

function cleanNumber(value) {
  return String(value ?? "")
    .replace(/[₹,%]/g, "")
    .replace(/,/g, "")
    .trim();
}

function cleanDate(value) {
  const text = String(value ?? "").trim();
  if (!text) return "";
  const normalized = text.replace(/\//g, "-");
  const match = normalized.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (match) {
    return `${match[1]}-${String(match[2]).padStart(2, "0")}-${String(match[3]).padStart(2, "0")}`;
  }
  return text;
}

function yesNo(value) {
  const text = String(value ?? "").trim().toLowerCase();
  if (["true", "yes", "y", "1", "active"].includes(text)) return "Yes";
  if (["false", "no", "n", "0", "inactive"].includes(text)) return "No";
  return String(value ?? "").trim();
}

const spreadsheetId = pick("spreadsheet_id", "spreadsheetId", "Spreadsheet ID");
if (!spreadsheetId) {
  throw new Error(`Missing spreadsheet_id. Open the form from Wealthyo dashboard. Fields received: ${Object.keys(fields).join(", ")}`);
}

return [
  {
    json: {
      customer_id: pick("customer_id", "customerId", "Customer ID"),
      spreadsheet_id: spreadsheetId,
      tab_name: pick("tab_name", "tabName") || "GoldChit",
      source: pick("source") || "wealthyo_dashboard_gold_chit",

      scheme_name: pick("scheme_name", "Scheme Name"),
      jeweller_name: pick("jeweller_name", "Jeweller Name"),
      branch: pick("branch", "Branch"),
      salesperson_name: pick("salesperson_name", "Salesperson Name"),
      salesperson_number: pick("salesperson_number", "Salesperson Number"),
      payment_type: pick("payment_type", "Payment Type"),
      start_date: cleanDate(pick("start_date", "Start Date")),
      end_date: cleanDate(pick("end_date", "End Date")),
      scheme_credit_method: pick("scheme_credit_method", "Scheme Credit Method"),
      gold_rate_at_payment: cleanNumber(pick("gold_rate_at_payment", "Gold Rate At Payment")),
      wastage_free_percent: cleanNumber(pick("wastage_free_percent", "Wastage Free Percent")),
      maturity_wait_months: cleanNumber(pick("maturity_wait_months", "Maturity Wait Months")),
      receipt_or_account_number: pick("receipt_or_account_number", "Receipt Or Account Number"),
      is_active: yesNo(pick("is_active", "Is Active")),
      notes: pick("notes", "Notes")
    }
  }
];
